## Dijkstra Implementation

Create this file at `src/lib/routing/dijkstra.ts`:

```typescript
import { PrismaClient, TransportMode } from "../../generated/prisma";

const prisma = new PrismaClient();

// ─── Types ────────────────────────────────────────────────

export interface RouteOptions {
  // Weights must add up to 1.0 — controls what "optimal" means
  // e.g. { distanceW: 0.2, fareW: 0.5, timeW: 0.3 } = fare-priority
  distanceW: number;
  fareW: number;
  timeW: number;
}

export interface RouteStep {
  fromNodeId: string;
  fromNodeName: string;
  toNodeId: string;
  toNodeName: string;
  transportMode: TransportMode;
  distanceM: number;
  travelTimeMin: number;
  estimatedFare: number;
  jeepneyColor?: string | null;
  todaZone?: string | null;
  instruction: string; // human-readable step
}

export interface RouteResult {
  found: boolean;
  steps: RouteStep[];
  totalDistanceM: number;
  totalTimeMin: number;
  totalFare: number;
  transferCount: number;
}

// ─── Graph loader ─────────────────────────────────────────
// Load the full graph from DB into memory once per request.
// For your scale (hundreds of nodes) this is perfectly fine.

interface GraphEdge {
  id: string;
  toNodeId: string;
  toNodeName: string;
  transportMode: TransportMode;
  distanceM: number;
  travelTimeMin: number;
  estimatedFare: number;
  transferPenalty: number;
  jeepneyColor: string | null;
  todaZoneName: string | null;
}

type Graph = Map<string, GraphEdge[]>;

async function loadGraph(): Promise<Graph> {
  const edges = await prisma.edge.findMany({
    include: {
      toNode: { select: { id: true, name: true } },
      jeepneyRoute: { select: { colorCode: true } },
      todaZone: { select: { zoneName: true } },
    },
  });

  const graph: Graph = new Map();

  for (const edge of edges) {
    if (!graph.has(edge.fromNodeId)) {
      graph.set(edge.fromNodeId, []);
    }

    graph.get(edge.fromNodeId)!.push({
      id: edge.id,
      toNodeId: edge.toNodeId,
      toNodeName: edge.toNode.name,
      transportMode: edge.transportMode,
      distanceM: Number(edge.distanceM),
      travelTimeMin: Number(edge.travelTimeMin),
      estimatedFare: Number(edge.estimatedFare),
      transferPenalty: Number(edge.transferPenalty),
      jeepneyColor: edge.jeepneyRoute?.colorCode ?? null,
      todaZoneName: edge.todaZone?.zoneName ?? null,
    });
  }

  return graph;
}

// ─── Cost function ────────────────────────────────────────
// This is the core of your thesis — the weighted composite cost.
// Normalise each metric so they're on the same scale before weighting.

const NORMALIZE = {
  maxDistanceM: 10_000,  // assume max single edge = 10km
  maxFare: 100,          // assume max single edge fare = ₱100
  maxTimeMin: 60,        // assume max single edge time = 60min
  transferPenaltyMin: 5, // each transfer = 5 "virtual" minutes added
};

function computeEdgeCost(edge: GraphEdge, opts: RouteOptions): number {
  const normDistance = edge.distanceM / NORMALIZE.maxDistanceM;
  const normFare = edge.estimatedFare / NORMALIZE.maxFare;
  const normTime =
    (edge.travelTimeMin + edge.transferPenalty) / NORMALIZE.maxTimeMin;

  return (
    opts.distanceW * normDistance +
    opts.fareW * normFare +
    opts.timeW * normTime
  );
}

// ─── Min-Heap (Priority Queue) ────────────────────────────
// JavaScript has no built-in heap, so we implement a simple one.
// This keeps Dijkstra at O((V + E) log V) instead of O(V²).

interface HeapNode {
  nodeId: string;
  cost: number;
}

class MinHeap {
  private heap: HeapNode[] = [];

  push(item: HeapNode) {
    this.heap.push(item);
    this._bubbleUp(this.heap.length - 1);
  }

  pop(): HeapNode | undefined {
    if (this.heap.length === 0) return undefined;
    const top = this.heap[0];
    const last = this.heap.pop()!;
    if (this.heap.length > 0) {
      this.heap[0] = last;
      this._sinkDown(0);
    }
    return top;
  }

  get size() {
    return this.heap.length;
  }

  private _bubbleUp(i: number) {
    while (i > 0) {
      const parent = Math.floor((i - 1) / 2);
      if (this.heap[parent].cost <= this.heap[i].cost) break;
      [this.heap[parent], this.heap[i]] = [this.heap[i], this.heap[parent]];
      i = parent;
    }
  }

  private _sinkDown(i: number) {
    const n = this.heap.length;
    while (true) {
      let smallest = i;
      const l = 2 * i + 1;
      const r = 2 * i + 2;
      if (l < n && this.heap[l].cost < this.heap[smallest].cost) smallest = l;
      if (r < n && this.heap[r].cost < this.heap[smallest].cost) smallest = r;
      if (smallest === i) break;
      [this.heap[smallest], this.heap[i]] = [this.heap[i], this.heap[smallest]];
      i = smallest;
    }
  }
}

// ─── Dijkstra ─────────────────────────────────────────────

export async function findRoute(
  startNodeId: string,
  endNodeId: string,
  opts: RouteOptions = { distanceW: 0.2, fareW: 0.5, timeW: 0.3 }
): Promise<RouteResult> {

  const graph = await loadGraph();

  // cost[nodeId] = best total cost found so far to reach this node
  const cost: Map<string, number> = new Map();
  // prev[nodeId] = the edge we took to get here (for path reconstruction)
  const prev: Map<string, { fromNodeId: string; edge: GraphEdge } | null> =
    new Map();
  // how many transfers happened on the best path to each node
  const transfers: Map<string, number> = new Map();
  // what transport mode we arrived at each node with
  const arrivalMode: Map<string, TransportMode | null> = new Map();

  cost.set(startNodeId, 0);
  prev.set(startNodeId, null);
  transfers.set(startNodeId, 0);
  arrivalMode.set(startNodeId, null);

  const pq = new MinHeap();
  pq.push({ nodeId: startNodeId, cost: 0 });

  while (pq.size > 0) {
    const current = pq.pop()!;

    // Early exit — we found the destination
    if (current.nodeId === endNodeId) break;

    // Skip if we already found a better path to this node
    if (current.cost > (cost.get(current.nodeId) ?? Infinity)) continue;

    const neighbors = graph.get(current.nodeId) ?? [];

    for (const edge of neighbors) {
      const edgeCost = computeEdgeCost(edge, opts);
      const newCost = current.cost + edgeCost;

      if (newCost < (cost.get(edge.toNodeId) ?? Infinity)) {
        cost.set(edge.toNodeId, newCost);
        prev.set(edge.toNodeId, { fromNodeId: current.nodeId, edge });

        // Track transfers: WALK edges between modes count as a transfer
        const prevMode = arrivalMode.get(current.nodeId) ?? null;
        const isTransfer =
          edge.transportMode === TransportMode.WALK && prevMode !== null;
        transfers.set(
          edge.toNodeId,
          (transfers.get(current.nodeId) ?? 0) + (isTransfer ? 1 : 0)
        );
        arrivalMode.set(edge.toNodeId, edge.transportMode);

        pq.push({ nodeId: edge.toNodeId, cost: newCost });
      }
    }
  }

  // ─── Path not found ───────────────────────────────────
  if (!prev.has(endNodeId) && endNodeId !== startNodeId) {
    return {
      found: false,
      steps: [],
      totalDistanceM: 0,
      totalTimeMin: 0,
      totalFare: 0,
      transferCount: 0,
    };
  }

  // ─── Reconstruct path ─────────────────────────────────
  // Walk backwards from endNode to startNode using prev map

  const steps: RouteStep[] = [];
  let currentId: string | undefined = endNodeId;

  while (currentId && currentId !== startNodeId) {
    const record = prev.get(currentId);
    if (!record) break;

    const { fromNodeId, edge } = record;

    // Get the fromNode name — it's stored in the edge going OUT from it,
    // so we find it from the graph
    const fromNodeName =
      graph.get(fromNodeId)?.[0]
        ? await getNodeName(fromNodeId)
        : fromNodeId;

    steps.unshift({
      fromNodeId,
      fromNodeName,
      toNodeId: edge.toNodeId,
      toNodeName: edge.toNodeName,
      transportMode: edge.transportMode,
      distanceM: edge.distanceM,
      travelTimeMin: edge.travelTimeMin,
      estimatedFare: edge.estimatedFare,
      jeepneyColor: edge.jeepneyColor,
      todaZone: edge.todaZoneName,
      instruction: buildInstruction(edge),
    });

    currentId = fromNodeId;
  }

  const totalDistanceM = steps.reduce((sum, s) => sum + s.distanceM, 0);
  const totalTimeMin = steps.reduce((sum, s) => sum + s.travelTimeMin, 0);
  const totalFare = steps.reduce((sum, s) => sum + s.estimatedFare, 0);
  const transferCount = transfers.get(endNodeId) ?? 0;

  return {
    found: true,
    steps,
    totalDistanceM,
    totalTimeMin,
    totalFare,
    transferCount,
  };
}

// ─── Helpers ──────────────────────────────────────────────

async function getNodeName(nodeId: string): Promise<string> {
  const node = await prisma.node.findUnique({
    where: { id: nodeId },
    select: { name: true },
  });
  return node?.name ?? nodeId;
}

function buildInstruction(edge: GraphEdge): string {
  switch (edge.transportMode) {
    case TransportMode.JEEPNEY:
      return `Ride the ${edge.jeepneyColor ?? ""} Jeepney to ${edge.toNodeName} (₱${edge.estimatedFare.toFixed(2)})`;
    case TransportMode.TODA:
      return `Take a tricycle (${edge.todaZoneName ?? "TODA"}) to ${edge.toNodeName} (₱${edge.estimatedFare.toFixed(2)})`;
    case TransportMode.WALK:
      return `Walk to ${edge.toNodeName} (~${Math.round(edge.travelTimeMin)} min)`;
  }
}
